const calculateRequestStage = ({ quotationEndTime, extendedQuotationEndTime, graceEndTime, targetTime, createdAt, isExpired }) => {
  const now = Date.now();
  const createdMs = createdAt ? new Date(createdAt).getTime() : 0;
  const qEndMs = quotationEndTime
    ? new Date(quotationEndTime).getTime()
    : (createdMs ? createdMs + 20 * 60 * 1000 : 0);
  const extEndMs = extendedQuotationEndTime
    ? new Date(extendedQuotationEndTime).getTime()
    : (qEndMs ? qEndMs + 10 * 60 * 1000 : (createdMs ? createdMs + 30 * 60 * 1000 : 0));
  const graceEndMs = graceEndTime
    ? new Date(graceEndTime).getTime()
    : (targetTime ? new Date(targetTime).getTime() : (extEndMs ? extEndMs + 5 * 60 * 1000 : (createdMs ? createdMs + 35 * 60 * 1000 : 0)));

  if (isExpired || (graceEndMs > 0 && now >= graceEndMs)) {
    return { stage: 'expired', remaining: 0, qEndMs, extEndMs, graceEndMs, now };
  }
  if (qEndMs > 0 && now < qEndMs) {
    return {
      stage: 'waiting',
      remaining: Math.max(0, Math.floor((qEndMs - now) / 1000)),
      qEndMs,
      extEndMs,
      graceEndMs,
      now
    };
  }
  // if (extEndMs > 0 && now < extEndMs) {
  //   return {
  //     stage: 'order',
  //     remaining: Math.max(0, Math.floor((extEndMs - now) / 1000)),
  //     qEndMs,
  //     extEndMs,
  //     graceEndMs,
  //     now
  //   };
  // }
  if (graceEndMs > 0 && now < graceEndMs) {
    return {
      stage: 'grace',
      remaining: Math.max(0, Math.floor((graceEndMs - now) / 1000)),
      qEndMs,
      extEndMs,
      graceEndMs,
      now
    };
  }
  return { stage: 'expired', remaining: 0, qEndMs, extEndMs, graceEndMs, now };
};

const formatCountdownStr = (secs) => {
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  if (h > 0) {
    return `${String(h).padStart(2, '0')}h ${String(m).padStart(2, '0')}m ${String(s).padStart(2, '0')}s`;
  }
  return `${String(m).padStart(2, '0')}m ${String(s).padStart(2, '0')}s`;
};

const formatTimeDisplayStr = (dateVal) => {
  if (!dateVal) return "N/A";
  const d = new Date(dateVal);
  if (isNaN(d.getTime())) return "N/A";
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
};

