const CountdownTimer = ({ quotationEndTime, extendedQuotationEndTime, graceEndTime, targetDate, fallbackCreatedAt, onExpire }) => {
  const [timerState, setTimerState] = useState({ stage: 'waiting', remaining: 0 });

  useEffect(() => {
    const calculateTimeLeft = () => {
      const nowMs = Date.now();
      const createdMs = fallbackCreatedAt ? new Date(fallbackCreatedAt).getTime() : 0;

      const qEndMs = quotationEndTime
        ? new Date(quotationEndTime).getTime()
        : (createdMs ? createdMs + 20 * 60 * 1000 : 0);

      // const orderEndMs = graceEndTime
      //   ? new Date(graceEndTime).getTime()
      //   : (extendedQuotationEndTime
      //     ? new Date(extendedQuotationEndTime).getTime()
      //     : (targetDate
      //       ? new Date(targetDate).getTime()
      //       : (qEndMs ? qEndMs + 15 * 60 * 1000 : (createdMs ? createdMs + 35 * 60 * 1000 : 0))));
      const orderEndMs = graceEndTime
        ? new Date(graceEndTime).getTime()
        : (targetDate
          ? new Date(targetDate).getTime()
          : (qEndMs ? qEndMs + 15 * 60 * 1000 : (createdMs ? createdMs + 35 * 60 * 1000 : 0)));

      if (qEndMs > 0 && nowMs < qEndMs) {
        return {
          stage: 'waiting',
          remaining: Math.max(0, Math.floor((qEndMs - nowMs) / 1000))
        };
      } else if (orderEndMs > 0 && nowMs < orderEndMs) {
        return {
          stage: 'order',
          remaining: Math.max(0, Math.floor((orderEndMs - nowMs) / 1000))
        };
      } else {
        return {
          stage: 'expired',
          remaining: 0
        };
      }
    };

    const initial = calculateTimeLeft();
    setTimerState(initial);
    if (initial.remaining <= 0 && onExpire) {
      onExpire();
      return;
    }

    const interval = setInterval(() => {
      const current = calculateTimeLeft();
      setTimerState(current);
      if (current.remaining <= 0 && current.stage === 'expired') {
        clearInterval(interval);
        if (onExpire) {
          onExpire();
        }
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [quotationEndTime, extendedQuotationEndTime, graceEndTime, targetDate, fallbackCreatedAt, onExpire]);

  if (timerState.stage === 'expired' || timerState.remaining <= 0) {
    return (
      <span
        className="badge d-inline-flex align-items-center gap-1.5"
        style={{
          backgroundColor: "#F1F5F9",
          color: "#64748B",
          border: "1px solid #CBD5E1",
          borderRadius: "6px",
          padding: "6px 14px",
          fontSize: "13px",
          fontWeight: "600"
        }}
      >
        <FaClock size={13} />
        <span>Request Expired</span>
      </span>
    );
  }

  const hours = Math.floor(timerState.remaining / 3600);
  const minutes = Math.floor((timerState.remaining % 3600) / 60);
  const seconds = timerState.remaining % 60;

  const formattedTime = hours > 0
    ? `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
    : `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;

  if (timerState.stage === 'waiting') {
    return (
      <span
        className="badge d-inline-flex align-items-center"
        style={{
          backgroundColor: "#DCFCE7",
          color: "#15803D",
          border: "1px solid #86EFAC",
          borderRadius: "6px",
          padding: "6px 14px",
          fontSize: "13px",
          fontWeight: "700"
        }}
      >
        <FaClock size={13} style={{ marginRight: "6px" }} />
        <span>
          Waiting <span style={{ fontFamily: "monospace", fontSize: "14px", fontWeight: "800", margin: "0 5px" }}>{formattedTime}</span> mins to get all Quotations
        </span>
      </span>
    );
  }

  // Stage 2: Next 15 mins (order placement window)
  return (
    <span
      className="badge d-inline-flex align-items-center"
      style={{
        backgroundColor: "#FFF7ED",
        color: "#C2410C",
        border: "1px solid #FDBA74",
        borderRadius: "6px",
        padding: "6px 14px",
        fontSize: "13px",
        fontWeight: "700"
      }}
    >
      <FaClock size={13} style={{ marginRight: "6px" }} />
      <span>
        Time Remaining to Place order: <span style={{ fontFamily: "monospace", fontSize: "14px", fontWeight: "800", marginLeft: "5px" }}>{formattedTime}</span>
      </span>
    </span>
  );
};

