        const isExpired = reqStatusUpper === "EXPIRED" || reqStatusUpper === "CANCELLED" || reqStatusUpper === "REJECTED" || (req.graceEndTime && new Date(req.graceEndTime) <= new Date());
        const quotationCount = req.quotationCount || 0;

